describe('Profile Wizard Autosave', () => {
  it('restores autosaved progress after reload', () => {
    cy.clock();
    cy.visit('/profile/new');
    cy.get('#firstName').type('Alex');
    cy.tick(120000);
    cy.window().then(win => {
      const data = JSON.parse(win.localStorage.getItem('profile_wizard'));
      expect(data?.firstName).to.eq('Alex');
    });
    cy.reload();
    cy.get('#firstName').should('have.value', 'Alex');
